  "inlineSchema": "// Prisma Schema for Morgan Shuttle App (MySQL Version)\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  binaryTargets = [\"native\", \"windows\", \"linux-musl-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id               String    @id @default(cuid())\n  name             String\n  email            String    @unique\n  role             String // admin, driver, tenant\n  password         String?\n  password_set     Boolean   @default(false)\n  invitation_sent  Boolean   @default(false)\n  invitation_token String?   @unique\n  token_expiry     DateTime?\n  source           String    @default(\"INTERNAL\") // PMS, INTERNAL\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n  bookings         Booking[]\n\n  @@map(\"user\")\n}\n\nmodel Trip {\n  id              String    @id @default(cuid())\n  time            String // HH:mm\n  date            String // YYYY-MM-DD\n  origin          String\n  destination     String\n  seats_total     Int       @default(7)\n  seats_remaining Int       @default(7)\n  status          String    @default(\"scheduled\") // scheduled, completed, cancelled, in_progress\n  is_special      Boolean   @default(false)\n  tenant_name     String?\n  lat             Float? // Current latitude for live tracking\n  lng             Float? // Current longitude for live tracking\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n  bookings        Booking[]\n\n  @@map(\"trip\")\n}\n\nmodel TripRequest {\n  id          String   @id @default(cuid())\n  tenant_name String\n  date        String\n  time        String\n  origin      String\n  destination String\n  passengers  Int\n  status      String   @default(\"pending\") // pending, approved, rejected\n  source      String   @default(\"tenant\") // tenant, admin\n  notes       String?  @db.Text\n  createdAt   DateTime @default(now())\n\n  @@map(\"triprequest\")\n}\n\nmodel Booking {\n  id          String   @id @default(cuid())\n  trip_id     String\n  trip        Trip     @relation(fields: [trip_id], references: [id])\n  user_id     String\n  user        User     @relation(fields: [user_id], references: [id])\n  time        String\n  date        String\n  origin      String\n  destination String\n  seats       Int\n  status      String   @default(\"confirmed\") // confirmed, cancelled\n  createdAt   DateTime @default(now())\n\n  @@map(\"booking\")\n}\n\nmodel FuelLog {\n  id        String   @id @default(cuid())\n  date      String\n  vehicle   String\n  gallons   Float\n  amount    Float\n  odometer  Float\n  createdAt DateTime @default(now())\n\n  @@map(\"fuellog\")\n}\n\nmodel MaintenanceLog {\n  id          String   @id @default(cuid())\n  date        String\n  vehicle     String\n  description String\n  cost        Float\n  createdAt   DateTime @default(now())\n\n  @@map(\"maintenancelog\")\n}\n\nmodel Destination {\n  id        String   @id @default(cuid())\n  name      String   @unique\n  createdAt DateTime @default(now())\n\n  @@map(\"destination\")\n}\n",
